import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

@Component({
  selector: 'app-saved-jobs',
  templateUrl: './saved-jobs.component.html',
  styleUrls: ['./saved-jobs.component.css']
})
export class SavedJobsComponent {
 allJobs: Job[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';

  constructor(
    private jobService: JobService,
    private companyService: CompanyService,
    private jobSeekerService: JobseekerService,
    private router: Router,
    private route : ActivatedRoute
  ) {}

  ngOnInit(): void {

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');
      const id = Number(localStorage.getItem('id'));

      if (role === 'COMPANY') {

        this.profileRoute = '/company/dashboard';

        this.companyService.getCompanyById(id).subscribe({
          next: (company: any) => {
            if (company?.companyName) {
              this.initials = company.companyName
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });

      } else {

        this.profileRoute = '/seeker/dashboard';

        this.jobSeekerService.getJobSeekerById(id).subscribe({
          next: (user: any) => {


            const name =
              user.userName ??
              `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim();

            if (name) {
              this.initials = name
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });
      }
    }

const jobseekerId : number = Number( localStorage.getItem("id"));

this.getAllSavedJobs(jobseekerId);



  }




  logout(): void {
    localStorage.clear();
    this.router.navigate(['/']);
  }

  goToProfile(): void {
    this.router.navigate([this.profileRoute]);
  }
  totalSavedJobs! : number;
  savedJobs! : Job[] ;

  getAllSavedJobs(jobSeekerId : number){
    this.jobService.getSavedJobs(jobSeekerId).subscribe({
      next : (result) => {
      this.savedJobs = result;
      this.totalSavedJobs = this.savedJobs.length;
      },
      error : (err) => {
        console.log(err);
      }
    });
  }

   jobseekerId : number = Number( localStorage.getItem("id"));
    jobId = Number(this.route.snapshot.paramMap.get("id"));

  // removeSavedJob(jobId : number ){
  //    this.jobService.removeSavedJob(jobId, this.jobseekerId).subscribe({
  //     next : (result) => {

  //     this.savedJobs = this.savedJobs.filter(
  //       job => Number(job.jobId) !== jobId
  //     );

  //     this.totalSavedJobs = this.savedJobs.length;
  //     this.getAllSavedJobs(this.jobseekerId);
  //     },
  //     error : (err) => {
  //       console.log(err);
  //     }
  //   });
  // }
  removeSavedJob(jobId: number) {

  console.log("Clicked remove:", jobId);

  this.jobService.removeSavedJob(jobId, this.jobseekerId).subscribe({
    next: () => {

      console.log("Before remove:", this.savedJobs);

      this.savedJobs = this.savedJobs.filter(
        job => Number(job.jobId) !== Number(jobId)
      );

      console.log("After remove:", this.savedJobs);

      this.totalSavedJobs = this.savedJobs.length;
    },
    error: (err) => {
      console.log(err);
    }
  });
}
}
<div class="page">
  <app-header variant="guest"></app-header>

  <div class="app-shell">
    <main class="main">

      <div class="page-title">Saved Jobs</div>
      <div class="page-sub">{{totalSavedJobs}} roles you've bookmarked to apply to later.</div>
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>Role</th>
              <th>Company</th>
              <th>Salary</th>
              <th>Saved On</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let job of savedJobs">
              <td>{{job.jobTitle}}</td>
              <td>{{job.companyName}}</td>
              <td>{{job.salary | currency}}</td>
              <td>2 days ago</td>
              <td class="actions">
                <a [routerLink]="['/job/view-job', job.jobId]">Apply</a><a class="danger" style="cursor: pointer;" (click)="removeSavedJob(+job.jobId)">Remove</a>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

    </main>
  </div>
</div>
